import catalogR1 from '../data/buildle/catalog-r1.json';
import {
  guessPool,
  isAllowedGuess,
  isInSkillPool,
  type Difficulty,
} from './modes';
import { skills, type Skill } from './skills';

/**
 * One documented skill bar a boss uses. Alternative bars are separate
 * variants; their skills are never merged. Generated by
 * scripts/buildle/build-dataset.mjs.
 */
export type BuildleVariant = {
  id: string;
  /** Player skill IDs, in source order. Never more than eight. */
  skillIds: number[];
  encounter: {
    campaign: string;
    locations: string[];
    /** Location notes and conditions, e.g. "only during The False Gods". */
    details: string[];
  };
  sources: { site: string; url: string; revisionId: number | null }[];
  /** When the sources were read and cross-checked. */
  checkedOn: string;
  /**
   * Skills that must not be hidden in a mode, e.g. because another documented
   * bar (possibly one outside the release) shows the same clue.
   */
  excludedTargets: { skillId: number; mode: string; reason: string }[];
  notes: string[];
};

export type BuildleBoss = {
  id: string;
  name: string;
  variants: BuildleVariant[];
};

/** A round's fixed choice: one variant and the one skill hidden in it. */
export type BuildlePuzzle = {
  /** Only the identity is kept, so a saved Daily is self-contained. */
  boss: { id: string; name: string };
  variant: BuildleVariant;
  targetId: number;
};

/** A round is played until it is solved or the player gives up. */
export type RoundStatus = 'playing' | 'solved' | 'gave-up';

export type Slot =
  | { kind: 'revealed'; skill: Skill }
  | { kind: 'missing' }
  /** The hidden skill, shown once the round has ended. */
  | { kind: 'answer'; skill: Skill; status: 'solved' | 'gave-up' }
  | { kind: 'unused' };

export const SLOT_COUNT = 8;
/** v1 release criterion: bars with fewer skills are left out. */
export const MIN_SKILLS = 3;
/** Accepted incorrect guesses before the boss-name hint can be revealed. */
export const HINT_AFTER_INCORRECT = 5;

/** A published catalog revision (src/data/buildle/catalog-r*.json). Immutable once shipped. */
export type BuildleCatalog = {
  revision: number;
  attribution: string;
  bosses: BuildleBoss[];
};

/** Every shipped catalog revision, by number. Daily puzzles name theirs. */
export const buildleCatalogs: Record<number, BuildleCatalog> = { 1: catalogR1 };
/** The newest revision, used for Infinite rounds. */
export const latestCatalog: BuildleCatalog = catalogR1;
export const buildleBosses: BuildleBoss[] = latestCatalog.bosses;
export const buildleAttribution: string = latestCatalog.attribution;

/** A puzzle's stable identity within a catalog revision. */
export const puzzleKey = (variantId: string, skillId: number) => `${variantId}:${skillId}`;

const skillById = new Map(skills.map((skill) => [skill.id, skill]));

export function skillFor(id: number): Skill {
  const skill = skillById.get(id);

  if (!skill) {
    throw new Error(`Unknown skill ID ${id}`);
  }

  return skill;
}

/** Problems that would make a variant unusable; an empty list means valid. */
export function datasetProblems(bosses: readonly BuildleBoss[]): string[] {
  const problems: string[] = [];
  const variantIds = new Set<string>();

  for (const boss of bosses) {
    if (boss.variants.length === 0) {
      problems.push(`${boss.name}: no variants`);
    }

    for (const variant of boss.variants) {
      const where = `${boss.name} (${variant.id})`;

      if (variantIds.has(variant.id)) {
        problems.push(`${where}: duplicate variant ID`);
      }
      variantIds.add(variant.id);

      if (variant.skillIds.length < MIN_SKILLS || variant.skillIds.length > SLOT_COUNT) {
        problems.push(
          `${where}: ${variant.skillIds.length} skills (must be ${MIN_SKILLS}–${SLOT_COUNT})`,
        );
      }

      if (new Set(variant.skillIds).size !== variant.skillIds.length) {
        problems.push(`${where}: repeated skill`);
      }

      for (const id of variant.skillIds) {
        if (!isInSkillPool(id)) {
          problems.push(`${where}: skill ID ${id} is outside Skilldle's skill pool`);
        }
      }

      if (variant.sources.length === 0) {
        problems.push(`${where}: no source`);
      }

      for (const source of variant.sources) {
        if (!source.url.startsWith('https://') || !source.revisionId) {
          problems.push(`${where}: ${source.site} source lacks a URL or revision ID`);
        }
      }

      if (!/^\d{4}-\d{2}-\d{2}$/.test(variant.checkedOn)) {
        problems.push(`${where}: no check date`);
      }

      for (const excluded of variant.excludedTargets) {
        if (!variant.skillIds.includes(excluded.skillId)) {
          problems.push(`${where}: excluded target ${excluded.skillId} is not in the bar`);
        }
      }
    }
  }

  return problems;
}

/** True only when every skill on the bar is in Skilldle's normal pool. */
export function barInSkillPool(variant: BuildleVariant): boolean {
  return variant.skillIds.length > 0 && variant.skillIds.every(isInSkillPool);
}

/**
 * NM hides an elite skill; HM may hide any skill in the bar. Targets the
 * dataset excludes for this mode are never chosen.
 */
export function eligibleTargets(
  variant: BuildleVariant,
  difficulty: Difficulty,
): number[] {
  const excluded = new Set(
    variant.excludedTargets
      .filter((entry) => entry.mode === difficulty)
      .map((entry) => entry.skillId),
  );

  return variant.skillIds.filter(
    (id) => !excluded.has(id) && (difficulty === 'hm' || skillFor(id).elite),
  );
}

/**
 * What the player sees before solving: the set of visible skills (shown in
 * name order) and the bar size. Source order plays no part.
 */
function clueKey(variant: BuildleVariant, targetId: number): string {
  const visible = variant.skillIds
    .filter((id) => id !== targetId)
    .sort((first, second) => first - second);
  return `${variant.skillIds.length}:${visible.join(',')}`;
}

/**
 * Every puzzle a difficulty can offer, minus ambiguous ones: when two
 * puzzles show the same clue (same visible skills and bar size) but hide
 * different skills, the player cannot tell which answer is wanted, so both
 * are left out. The data pipeline already applies this across every
 * documented bar (including ones outside the release); this repeats the
 * check within the loaded data as a safeguard.
 */
export function puzzleCatalog(
  bosses: readonly BuildleBoss[],
  difficulty: Difficulty,
): { puzzles: BuildlePuzzle[]; ambiguous: BuildlePuzzle[] } {
  const byClue = new Map<string, BuildlePuzzle[]>();

  for (const boss of bosses) {
    for (const variant of boss.variants) {
      // The complete bar must be in Skilldle's pool; a bar with any other
      // skill offers no puzzle at all, in either mode.
      if (!barInSkillPool(variant)) {
        continue;
      }

      for (const targetId of eligibleTargets(variant, difficulty)) {
        const key = clueKey(variant, targetId);
        byClue.set(key, [...(byClue.get(key) ?? []), { boss, variant, targetId }]);
      }
    }
  }

  const puzzles: BuildlePuzzle[] = [];
  const ambiguous: BuildlePuzzle[] = [];

  for (const group of byClue.values()) {
    const answers = new Set(group.map((puzzle) => puzzle.targetId));
    (answers.size > 1 ? ambiguous : puzzles).push(...group);
  }

  return { puzzles, ambiguous };
}

export function randomPuzzle(
  puzzles: readonly BuildlePuzzle[],
  random: () => number = Math.random,
  avoid?: BuildlePuzzle,
): BuildlePuzzle | null {
  if (puzzles.length === 0) {
    return null;
  }

  // Do not repeat the round that just ended when there is any other choice.
  const choices =
    avoid && puzzles.length > 1
      ? puzzles.filter(
          (puzzle) =>
            puzzle.variant.id !== avoid.variant.id ||
            puzzle.targetId !== avoid.targetId,
        )
      : puzzles;

  return choices[Math.floor(random() * choices.length)];
}

/**
 * Always eight slots: the visible skills in name order, then the missing
 * skill, then unused slots. The missing slot's position never depends on
 * which skill is hidden, so it gives nothing away (source lists are often
 * alphabetical). Once the round ends, the hidden skill appears in its slot.
 */
export function buildSlots(puzzle: BuildlePuzzle, status: RoundStatus): Slot[] {
  const slots: Slot[] = puzzle.variant.skillIds
    .filter((id) => id !== puzzle.targetId)
    .map(skillFor)
    .sort((first, second) => first.name.localeCompare(second.name))
    .map((skill) => ({ kind: 'revealed', skill }));

  slots.push(
    status === 'playing'
      ? { kind: 'missing' }
      : { kind: 'answer', skill: skillFor(puzzle.targetId), status },
  );

  while (slots.length < SLOT_COUNT) {
    slots.push({ kind: 'unused' });
  }

  return slots;
}

export type GuessCheck =
  | { kind: 'invalid' }
  | { kind: 'duplicate'; skill: Skill }
  | { kind: 'not-elite'; skill: Skill }
  | { kind: 'correct'; skill: Skill }
  | { kind: 'incorrect'; skill: Skill };

// Guesses resolve only to skills in Skilldle's normal pool (the HM pool);
// NM then narrows to elites with Skilldle's own rule.
const skillByNormalizedName = new Map(
  guessPool('hm').map((skill) => [skill.name.trim().toLocaleLowerCase(), skill]),
);

/**
 * Right or wrong only. Invalid (including any name outside Skilldle's pool),
 * duplicate, and (in NM) non-elite guesses are rejected without being
 * recorded. Naming a skill that is already visible is a valid guess, and
 * incorrect.
 */
export function checkGuess(
  input: string,
  puzzle: BuildlePuzzle,
  difficulty: Difficulty,
  guessedIds: readonly number[],
): GuessCheck {
  const skill = skillByNormalizedName.get(input.trim().toLocaleLowerCase());

  if (!skill) {
    return { kind: 'invalid' };
  }

  if (guessedIds.includes(skill.id)) {
    return { kind: 'duplicate', skill };
  }

  if (!isAllowedGuess(difficulty, skill)) {
    return { kind: 'not-elite', skill };
  }

  return skill.id === puzzle.targetId
    ? { kind: 'correct', skill }
    : { kind: 'incorrect', skill };
}

export function hintAvailable(incorrectGuesses: number): boolean {
  return incorrectGuesses >= HINT_AFTER_INCORRECT;
}
